<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <div class="hero">
        <p class="eyebrow">Mini assessment</p>
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p class="intro">Choose every answer that applies. Some questions have more than one correct choice.</p>
      </div>

      <form id="quiz-form">
        <div class="form-field">
          <fieldset aria-describedby="question-1-help">
            <legend>1. Which of these are programming languages?</legend>
            <p class="help-text" id="question-1-help">Select all languages used to write instructions that computers can execute or interpret.</p>
            <div class="choices">
              <label class="choice">
                <input type="checkbox" name="question-1" value="python">
                <span>Python</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-1" value="html">
                <span>HTML</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-1" value="javascript">
                <span>JavaScript</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-1" value="sql">
                <span>SQL</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which languages are commonly used for front-end web development?</legend>
            <div class="choices">
              <label class="choice">
                <input type="checkbox" name="question-2" value="css">
                <span>CSS</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-2" value="javascript">
                <span>JavaScript</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-2" value="html">
                <span>HTML</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-2" value="assembly">
                <span>Assembly</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which languages are often associated with data analysis or machine learning?</legend>
            <div class="choices">
              <label class="choice">
                <input type="checkbox" name="question-3" value="python">
                <span>Python</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-3" value="r">
                <span>R</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-3" value="sql">
                <span>SQL</span>
              </label>
              <label class="choice">
                <input type="checkbox" name="question-3" value="css">
                <span>CSS</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit quiz</button>
          <p class="result" id="result" role="status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#quiz-form");
    const result = document.querySelector("#result");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const unanswered = ["question-1", "question-2", "question-3"].filter((name) => {
        return form.querySelectorAll(`input[name="${name}"]:checked`).length === 0;
      });

      result.classList.remove("success", "warning");

